const designs={quiet:{title:'A little play.<br class="phone-break"> A lot shipped.',description:'Turn your repo into a factory. Make a few decisions.<br class="desktop-break"> Ship real improvements.'},product:{title:'Your repo.<br>A working factory.',description:'Issues become plans. Your agents build.<br class="desktop-break"> You decide what ships.'},story:{title:'Less managing agents.<br>More shipping.',description:'A little play. A lot shipped.'}};
function selectDesign(name){if(!designs[name])name='quiet';document.body.dataset.design=name;document.querySelector('#hero-heading').innerHTML=designs[name].title;document.querySelector('#hero-description').innerHTML=designs[name].description;document.querySelectorAll('.workshop button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.design===name)));const u=new URL(location.href);u.searchParams.set('design',name);history.replaceState(null,'',u);document.title=`Shiptorio · ${name==='product'?'Factory':name[0].toUpperCase()+name.slice(1)} landing concept`;}
document.querySelectorAll('.workshop button').forEach(b=>b.addEventListener('click',()=>selectDesign(b.dataset.design)));selectDesign(new URLSearchParams(location.search).get('design'));
const demo=document.querySelector('#demo'),connect=document.querySelector('#connect');let step=0;
const steps=[{title:'One small issue. One real improvement.',body:'A customer found a confusing sign-in error. The factory proposes a small fix and a regression test.',detail:'Your decision: approve the plan before an agent starts.',button:'Approve the plan',stage:0},{title:'Your agent takes it from here.',body:'In the real factory, your local Codex or Claude agent builds the approved change and opens a pull request.',detail:'Preview: one scoped fix, one test, one PR. Your repo stays untouched here.',button:'See the checks',stage:1},{title:'Good work earns a green light.',body:'CI, regression proof and AI review inspect the exact commit. A failed check sends the work back for repair.',detail:'Preview: all checks passed. The final decision stays with you.',button:'Review for launch',stage:2},{title:'You decide what ships.',body:'The change is ready for a final look. In your factory, Launch merges the verified pull request.',detail:'This is a demo launch. It cannot merge a real PR.',button:'Launch the demo rocket',stage:3},{title:'One less bug. One more ship.',body:'That’s the loop: a small decision becomes a checked improvement. Then the factory finds the next bottleneck.',detail:'Demo complete. No account, build or repository was changed.',button:'Play again',stage:4}];
function paint(){const s=steps[step];document.querySelector('#demo-title').textContent=s.title;document.querySelector('#demo-body').textContent=s.body;document.querySelector('#demo-detail').textContent=s.detail;document.querySelector('#demo-next').firstChild.textContent=s.button+' ';document.querySelectorAll('.demo-track span').forEach((e,i)=>{e.classList.toggle('active',i===s.stage);e.classList.toggle('complete',i<s.stage)});document.querySelector('.demo-later').textContent=step===4?'Close preview':'Later';document.querySelector('.demo-announcement').textContent=step===4?'Demo rocket launched.':`Step ${step+1} of 5`;}
document.querySelectorAll('[data-play]').forEach(b=>b.addEventListener('click',()=>{step=0;paint();demo.showModal()}));document.querySelector('#demo-next').addEventListener('click',()=>{step=(step+1)%steps.length;paint()});document.querySelector('.demo-later').addEventListener('click',()=>demo.close());document.querySelectorAll('[data-connect]').forEach(b=>b.addEventListener('click',()=>connect.showModal()));document.querySelectorAll('dialog .close').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
